from __future__ import print_function
from __future__ import division

import sys
import six


if sys.version_info[0] < 3:
    text_type = unicode
    binary_type = str
else:
    text_type = str
    binary_type = bytes


def to_unicode(value):
    """Convert a value to unicode string.

    In Python 2: converts bytes or unicode to unicode.
    In Python 3: converts bytes or str to str.
    """
    if isinstance(value, binary_type):
        return value.decode('utf-8')
    return text_type(value)


def to_bytes(value):
    """Convert a value to bytes.

    In Python 2: converts bytes or unicode to str (bytes).
    In Python 3: converts str or bytes to bytes.
    """
    if isinstance(value, text_type):
        return value.encode('utf-8')
    return binary_type(value)


def to_text(value):
    """Convert a value to text (unicode in Py2, str in Py3).

    This is an alias for to_unicode for consistency with Python 3 naming.
    """
    return to_unicode(value)


def is_string(value):
    """Check if value is a string type (works in both Python 2 and 3).

    Uses six.string_types for compatibility.
    """
    return isinstance(value, six.string_types)


def is_text(value):
    """Check if value is a text type (unicode in Py2, str in Py3)."""
    return isinstance(value, text_type)


def is_binary(value):
    """Check if value is a binary type (bytes)."""
    return isinstance(value, binary_type)


def safe_divide(x, y):
    """Perform division that works consistently in Python 2 and 3.

    Uses true division by default (via __future__ import).
    In Python 2 without __future__, this would be integer division.
    """
    return x / y


def join_paths(*parts):
    """Join path parts using os.path.join.

    Handles unicode and bytes correctly in both Python versions.
    """
    import os.path
    return os.path.join(*parts)


def open_file(path, mode='r', encoding='utf-8'):
    """Open a file with proper unicode handling in both Python 2 and 3.

    Uses io.open for consistent unicode support.
    """
    import io
    return io.open(path, mode=mode, encoding=encoding)


def iteritems(d):
    """Iterate over dictionary items (compatible with Py2 and Py3).

    In Python 2, uses dict.iteritems() if available.
    In Python 3, uses dict.items().
    """
    return six.iteritems(d)


def iterkeys(d):
    """Iterate over dictionary keys (compatible with Py2 and Py3)."""
    return six.iterkeys(d)


def itervals(d):
    """Iterate over dictionary values (compatible with Py2 and Py3)."""
    return six.itervalues(d)
